#include "ArpoMethods.h"
#include "IEcoLab64.h"
#include "IEcoMemoryAllocator1.h"
#include <stdint.h>

static void ECOCALLMETHOD stage_job(void* context, uint32_t lane, uint32_t workers) {
    struct {
        uint32_t* indices;
        uint32_t* base;
        uint32_t width;
        uint32_t count;
        BitonicCompare compare;
        uint32_t k;
        uint32_t j;
    } *ctx = (struct *)context;

    uint32_t i = lane;
    while (i < ctx->count) {
        uint32_t partner = i ^ ctx->j;
        if (partner > i) {
            uint32_t idx1 = ctx->indices[i];
            uint32_t idx2 = ctx->indices[partner];
            int result = 0;
            if (idx1 < ctx->count) {
                if (idx2 < ctx->count) {
                    result = ctx->compare((char*)ctx->base + idx1 * ctx->width,
                                          (char*)ctx->base + idx2 * ctx->width);
                } else {
                    result = 1;
                }
            } else {
                if (idx2 < ctx->count) {
                    result = -1;
                } else {
                    result = 0;
                }
            }
            if (ctx->k == 1) {
                if (result > 0) {
                    ctx->indices[i] = idx2;
                    ctx->indices[partner] = idx1;
                }
            } else {
                int ascending = (i & ctx->k) == 0;
                if ((ascending && result > 0) || (!ascending && result < 0)) {
                    ctx->indices[i] = idx2;
                    ctx->indices[partner] = idx1;
                }
            }
        }
        i += workers;
    }
}

int16_t ECOCALLMETHOD lab_bitonic_sort(IEcoLab64* me, void* base, uint32_t count, uint32_t width, BitonicCompare compare, uint32_t workers, BitonicExecutor executor, void* executor_context, BitonicStats* stats) {
    if (!me || !compare || !base || !width || width > 1048576 || count > 1048576) {
        return -1;
    }

    uint32_t count_width = count * width;
    if (count_width < count) {
        return -1;
    }

    IEcoMemoryAllocator1* allocator = lab_allocator(me);
    if (!allocator) {
        return -2;
    }

    uint32_t padded_count = 1;
    while (padded_count < count) {
        padded_count <<= 1;
    }

    uint32_t* indices = (uint32_t*)allocator->pVTbl->Alloc(allocator, padded_count * sizeof(uint32_t));
    if (!indices) {
        return -2;
    }

    uint32_t* output = (uint32_t*)allocator->pVTbl->Alloc(allocator, count_width);
    if (!output) {
        allocator->pVTbl->Free(allocator, indices);
        return -2;
    }

    uint32_t i;
    for (i = 0; i < count; i++) {
        indices[i] = i;
    }

    for (i = count; i < padded_count; i++) {
        indices[i] = count;
    }

    uint32_t stages = 0;
    uint64_t network_pairs = 0;

    if (padded_count > 1) {
        uint32_t k = 2;
        while (k <= padded_count) {
            uint32_t j = k >> 1;
            while (j >= 1) {
                struct {
                    uint32_t* indices;
                    uint32_t* base;
                    uint32_t width;
                    uint32_t count;
                    BitonicCompare compare;
                    uint32_t k;
                    uint32_t j;
                } context;

                context.indices = indices;
                context.base = (uint32_t*)base;
                context.width = width;
                context.count = count;
                context.compare = compare;
                context.k = k;
                context.j = j;

                if (executor && workers > 1) {
                    int16_t result = executor(executor_context, stage_job, &context, workers);
                    if (result != 0) {
                        allocator->pVTbl->Free(allocator, indices);
                        allocator->pVTbl->Free(allocator, output);
                        return -3;
    }
                } else {
                    stage_job(&context, 0, 1);
                }

                network_pairs += padded_count / 2;
                j >>= 1;
            }
            k <<= 1;
            stages++;
        }
    }

    if (stats) {
